<!doctype html><html><head><meta charset="utf-8"><title>Public survey questions</title><style>body{font-family:Arial;background:#f4f6f8}main{max-width:1100px;margin:25px auto}.panel{background:white;padding:18px;margin:15px 0}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}textarea,input{width:100%;box-sizing:border-box;padding:7px}.choices{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}</style></head><body><main><p><a href="<?= site_url('survey/list_survey') ?>">← Surveys</a></p><h1><?= esc($survey['sv_title_eng']??$survey['sv_title_th']??'Survey') ?></h1>
<?php $render=function($r=[]) use($survey){ ?><form class="panel" method="post" action="<?= site_url('public-survey/'.$survey['sv_id'].'/questions/save') ?>"><?= csrf_field() ?><?php if($r): ?><input type="hidden" name="svde_id" value="<?= esc($r['svde_id']) ?>"><?php endif ?><div class="grid"><?php foreach(['svde_type','svde_name_th','svde_info_th','svde_name_eng','svde_info_eng','svde_name_jp','svde_info_jp','svde_isMultichoice','svde_isSpecify','svde_status'] as $f): ?><label><?= esc($f) ?><textarea name="<?= esc($f) ?>"><?= esc($r[$f]??($f==='svde_status'?'1':'')) ?></textarea></label><?php endforeach ?></div><h3>Choices (up to 15)</h3><div class="choices"><?php foreach(['th','eng','jp'] as $lang){for($i=1;$i<=15;$i++){ $f="mul_c{$i}_{$lang}";?><input name="<?= $f ?>" placeholder="<?= $f ?>" value="<?= esc($r['choices'][$f]??'') ?>"><?php }} ?></div><button>Save question</button></form><?php }; foreach($rows as $row)$render($row); ?><h2>Add question</h2><?php $render(); ?></main></body></html>
